#[cfg(target_arch = "x86_64")]
fn probe(c: &mut Criterion) {
    use std::hint::black_box;
    use criterion::BenchmarkId;
    use verified_garbage::aes_gcm::{AesGcm, probe};
    use crate::VG;
    let nonce = [0x24; 12];
    let aad = [0x17, 0x03, 0x03, 0x40, 0x11];
    let ty = [0x17u8];
    for (bits, key) in [(128, &[0x42u8; 16][..]), (256, &[0x42u8; 32][..])] {
        let k = AesGcm::new(key).unwrap();
        let mut g = c.benchmark_group(format!("aes-{bits}-gcm-probe"));
        for size in [256usize, 1024, 16384] {
            let data = vec![0u8; size];
            let mut out = vec![0u8; size + 1];
            let mut buf = vec![0u8; size + 1];
            for _ in 0..64 {
                k.encrypt(&nonce, &aad, &[&data, &ty], &mut out).unwrap();
            }
            g.bench_function(BenchmarkId::new(VG, 1_000_000 + size), |b| {
                b.iter(|| k.encrypt(black_box(&nonce), black_box(&aad), &[black_box(&data[..]), black_box(&ty[..])], black_box(&mut out)).unwrap())
            });
            let rounds = if bits == 128 { 10 } else { 14 };
            g.bench_function(BenchmarkId::new(VG, 7_000_000 + size), |b| {
                b.iter(|| {
                    let mut w = core::mem::MaybeUninit::<[u64; 320]>::uninit();
                    let mut tag = [0u8; 16];
                    let o = black_box(&mut out);
                    o[size] = 0x17;
                    unsafe { proto_seal(probe::ctx(&k), rounds, black_box(&nonce).as_ptr(), aad.as_ptr(), aad.len(), black_box(&data).as_ptr(), size, o.as_mut_ptr(), size + 1, &mut tag, w.as_mut_ptr()) };
                    tag
                })
            });
            g.bench_function(BenchmarkId::new(VG, 8_000_000 + size), |b| {
                b.iter(|| {
                    let mut w = core::mem::MaybeUninit::<[u64; 320]>::uninit();
                    let mut tag = [0u8; 16];
                    let o = black_box(&mut out);
                    o[size] = 0x17;
                    unsafe { proto_seal_b(probe::ctx(&k), rounds, black_box(&nonce).as_ptr(), aad.as_ptr(), aad.len(), black_box(&data).as_ptr(), size, o.as_mut_ptr(), size + 1, &mut tag, w.as_mut_ptr()) };
                    tag
                })
            });
            {
                let n = size + 1;
                let mut ct = vec![0u8; n];
                let tag = k.encrypt_in_place(&nonce, &aad, &mut ct).unwrap();
                let mut buf = ct.clone();
                g.bench_function(BenchmarkId::new(VG, 9_000_000 + size), |b| {
                    b.iter(|| {
                        buf.copy_from_slice(&ct);
                        k.decrypt_in_place(black_box(&nonce), black_box(&aad), black_box(&mut buf), &tag).unwrap()
                    })
                });
                g.bench_function(BenchmarkId::new(VG, 10_000_000 + size), |b| {
                    b.iter(|| {
                        buf.copy_from_slice(&ct);
                        let mut w = core::mem::MaybeUninit::<[u64; 384]>::uninit();
                        let ok = unsafe { proto_open(probe::ctx(&k), rounds, black_box(&nonce).as_ptr(), aad.as_ptr(), aad.len(), black_box(&mut buf).as_mut_ptr(), n, &tag, w.as_mut_ptr()) };
                        assert_eq!(ok, 1);
                    })
                });
            }
            g.bench_function(BenchmarkId::new(VG, 3_000_000 + size), |b| {
                b.iter(|| k.encrypt_in_place(black_box(&nonce), black_box(&aad), black_box(&mut buf)).unwrap())
            });
            g.bench_function(BenchmarkId::new(VG, 4_000_000 + size), |b| {
                b.iter(|| probe::blocks(&k, black_box(&data), black_box(&mut out)))
            });
        }
        let mut blk = [0u8; 16];
        let mut y = [0u8; 16];
        let bl = [[0u8; 16]; 2];
        g.bench_function(BenchmarkId::new(VG, 5), |b| b.iter(|| probe::ctr1(&k, black_box(&mut blk))));
        g.bench_function(BenchmarkId::new(VG, 6), |b| b.iter(|| probe::gh(&k, black_box(&mut y), &bl[..1])));
        g.bench_function(BenchmarkId::new(VG, 7), |b| b.iter(|| probe::gh(&k, black_box(&mut y), &bl[..])));
        g.finish();
    }
}
#[cfg(not(target_arch = "x86_64"))]
fn probe(_: &mut Criterion) {}

#[cfg(not(any(
    target_arch = "x86_64",
    target_arch = "aarch64",
    target_arch = "arm",
    target_arch = "x86"
)))]
pub fn bench(_: &mut Criterion) {}
